}

/** Summe einer mit `rate` indexierten Zahlungsreihe von 1 über n Jahre */
function summeIndex(n, rate) {
  let s = 0;
  for (let t = 0; t < n; t++) s += Math.pow(1 + rate, t);
  return s;
}

function naechsteSchritte({ ampel, land, eigentum, netz, nutzung }) {
